import type { Sandbox } from "./sdk.js";
import type { SessionState } from "./types.js";
import { PROVIDERS, providerConfigScript, redactText, resolveProvider } from "./providers.js";

export const PASEO_CLI_VERSION = "0.9.1";
export const DEFAULT_PASEO_HOME = "/vercel/paseo-home";
export const DEFAULT_WORKSPACE = "/vercel/workspace";
export const DEFAULT_REPO_PATH = "/vercel/workspace/repo";

export const AGENT_CLI_PINS = Object.values(PROVIDERS).map((provider) =>
  Object.assign({}, provider, {
    spec: `${provider.package}@${provider.version}`,
  }),
);

function shellQuote(value: string): string {
  return `'${value.replaceAll("'", "'\\''")}'`;
}

export function bootstrapScript(state: SessionState): string {
  resolveProvider(state.agentProvider);

  return `#!/bin/bash
set -euo pipefail

PASEO_HOME=${shellQuote(state.paseoHome)}
export PASEO_HOME
WORKSPACE_PATH=${shellQuote(state.workspacePath)}
REPO_PATH=${shellQuote(state.repoPath)}
${state.repoUrl === undefined ? "" : `REPO_URL=${shellQuote(state.repoUrl)}\n`}
export PATH="$HOME/.npm-global/bin:$PATH"
export NPM_CONFIG_PREFIX="$HOME/.npm-global"

printf '== bootstrap paseo-sandbox %s ==\\n' ${shellQuote(state.name)}

node --version
npm --version

mkdir -p -- "$PASEO_HOME" "$WORKSPACE_PATH" "$REPO_PATH"

${
  state.repoUrl === undefined
    ? ""
    : `if [ -d "$REPO_PATH" ]; then
  if ! destination_entries="$(find "$REPO_PATH" -mindepth 1 -print -quit)"; then
    printf 'bootstrap repository failure: unable to inspect destination\\n' >&2
    exit 1
  fi

  if [ -n "$destination_entries" ]; then
    if [ ! -e "$REPO_PATH/.git" ] || ! git -C "$REPO_PATH" rev-parse --is-inside-work-tree >/dev/null 2>&1; then
      printf 'bootstrap repository failure: destination has unrelated contents\\n' >&2
      exit 1
    fi

    if ! existing_origin="$(git -C "$REPO_PATH" remote get-url origin)"; then
      printf 'bootstrap repository failure: existing checkout has no origin\\n' >&2
      exit 1
    fi

    if [ "$existing_origin" != "$REPO_URL" ]; then
      printf 'bootstrap repository failure: existing checkout origin does not match repoUrl\\n' >&2
      exit 1
    fi
  else
    if ! git clone -- "$REPO_URL" "$REPO_PATH"; then
      printf 'bootstrap repository failure: git clone failed\\n' >&2
      exit 1
    fi
  fi
else
  if ! git clone -- "$REPO_URL" "$REPO_PATH"; then
    printf 'bootstrap repository failure: git clone failed\\n' >&2
    exit 1
  fi
fi
`
}

check_cli() {
  local command_name="$1" package_spec="$2"
  local package_name="\${package_spec%@*}"
  local package_version="\${package_spec##*@}"
  local package_dir="$HOME/.npm-global/lib/node_modules/$package_name"
  if [ ! -d "$package_dir" ]; then
    npm install -g --allow-scripts=esbuild,node-pty "$package_name@$package_version"
  fi
  if [ -f "$package_dir/package.json" ] && ! node -e '
    const fs = require("node:fs");
    const pkg = JSON.parse(fs.readFileSync(process.argv[1], "utf8"));
    if (pkg.version !== process.argv[2]) process.exit(1);
  ' "$package_dir/package.json" "$package_version"; then
    printf 'bootstrap failure: installed %s does not match pinned version %s\\n' "$package_name" "$package_version" >&2
    exit 1
  fi
  command -v "$command_name" >/dev/null 2>&1 || {
    printf 'bootstrap failure: %s CLI is not executable on PATH\\n' "$command_name" >&2
    exit 1
  }
}

check_cli paseo @getpaseo/cli@${PASEO_CLI_VERSION}
${AGENT_CLI_PINS.map((pin) => `check_cli ${pin.binary} ${shellQuote(`${pin.package}@${pin.version}`)}`).join("\n")}

paseo --version
${AGENT_CLI_PINS.map((pin) => `${pin.binary} --version`).join("\n")}

PROVIDER_CONFIG_SCRIPT="$HOME/.paseo-sandbox/configure-providers.js"
mkdir -p -- "$HOME/.paseo-sandbox"
cat > "$PROVIDER_CONFIG_SCRIPT" <<'PASEO_PROVIDER_CONFIG_EOF'
${providerConfigScript(state)}
PASEO_PROVIDER_CONFIG_EOF
chmod 700 "$PROVIDER_CONFIG_SCRIPT"
export CLAUDE_CONFIG_DIR="$HOME/.claude"
export XDG_DATA_HOME="$HOME/.local/share"
export OPENCODE_CONFIG_DIR="$HOME/.config/opencode"
export PI_CODING_AGENT_DIR="$HOME/.pi/agent"
export OPENCODE_AUTH_CONTENT=
node "$PROVIDER_CONFIG_SCRIPT"

echo "bootstrap complete"
`;
}

export async function writeBootstrapToSandbox(
  sandbox: Sandbox,
  state: SessionState,
  signal?: AbortSignal,
): Promise<void> {
  const content = Buffer.from(bootstrapScript(state), "utf8");
  await sandbox.writeFiles([{ path: "/vercel/bootstrap.sh", content, mode: 0o755 }], { signal });
}

export async function runBootstrap(
  sandbox: Sandbox,
  _state: SessionState,
  gatewayKey: string,
  timeoutMs = 10 * 60 * 1000,
  signal?: AbortSignal,
): Promise<void> {
  const result = await sandbox.runCommand({
    cmd: "/bin/bash",
    args: ["/vercel/bootstrap.sh"],
    env: { AI_GATEWAY_API_KEY: gatewayKey },
    timeoutMs,
    signal,
  });
  const stdout = await result.stdout();
  const stderr = await result.stderr();
  if (result.exitCode !== 0) {
    throw new Error(
      redactText(`bootstrap failed (exit ${result.exitCode}):\n${stdout}\n${stderr}`, gatewayKey),
    );
  }
}

export const AGENT_IDS = ["codex", "claude", "opencode", "pi"] as const;
export type AgentId = (typeof AGENT_IDS)[number];

export const AGENT_DETAILS: Record<AgentId, { title: string; detail: string }> = {
  codex: { title: "Codex", detail: "OpenAI coding agent" },
  claude: { title: "Claude Code", detail: "Anthropic coding agent" },
  opencode: { title: "OpenCode", detail: "Open source coding agent" },
  pi: { title: "Pi", detail: "Minimal coding agent" },
};

import type { Sandbox } from "./sdk.js";
import { providerLaunchEnvironment, resolveProvider } from "./providers.js";
import type { SessionState } from "./types.js";

function shellQuote(value: string): string {
  return `'${value.replace(/'/g, `'"'"'`)}'`;
}

export async function providerDiagnostic(
  sandbox: Sandbox,
  state: SessionState,
  gatewayKey: string,
  timeoutMs = 180_000,
  signal?: AbortSignal,
): Promise<{
  ok: boolean;
  provider: string;
  providerMatched: boolean;
  status?: string;
  modelCount?: number;
  exitCode: number;
  parseError: boolean;
}> {
  const provider = resolveProvider(state.agentProvider);
  const result = await sandbox.runCommand({
    cmd: "bash",
    args: [
      "-lc",
      `export PASEO_HOME=${shellQuote(state.paseoHome)}; ` +
        `export PATH="$HOME/.npm-global/bin:$PATH"; ` +
        `export CLAUDE_CONFIG_DIR="$HOME/.claude"; ` +
        `export XDG_DATA_HOME="$HOME/.local/share"; ` +
        `export OPENCODE_CONFIG_DIR="$HOME/.config/opencode"; ` +
        `export PI_CODING_AGENT_DIR="$HOME/.pi/agent"; ` +
        `export OPENCODE_AUTH_CONTENT=; ` +
        `paseo provider diagnostic ${provider.id} --json`,
    ],
    env: providerLaunchEnvironment(gatewayKey, state.agentModel),
    timeoutMs,
    signal,
  });
  const stdout = await result.stdout();
  await result.stderr();
  let diagnosticText: string | undefined;
  let parseError = false;
  let payload: { diagnostic?: unknown; provider?: unknown } = {};
  try {
    payload = JSON.parse(stdout.trim() || "null") as { diagnostic?: unknown; provider?: unknown };
  if (typeof payload.diagnostic === "string") diagnosticText = payload.diagnostic;
  } catch {
    parseError = true;
  }
  const status = diagnosticText?.match(/Status:\s*([^\n]+)/i)?.[1]?.trim();
  const modelCount = diagnosticText?.match(/Models:\s*(\d+|—)/i)?.[1];
  const parsedModelCount = modelCount && modelCount !== "—" ? Number(modelCount) : undefined;
  return {
    ok: result.exitCode === 0 && !parseError && status?.toLowerCase() === "ready" &&
      parsedModelCount !== undefined && parsedModelCount > 0,
    provider: provider.id,
    providerMatched: payload.provider === undefined || payload.provider === provider.id,
    status,
    modelCount: parsedModelCount,
    exitCode: result.exitCode,
    parseError,
  };
}

import { build } from "esbuild";
import { execFileSync } from "node:child_process";
import { mkdir, copyFile, readFile, writeFile, rm } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { join } from "node:path";
const root = fileURLToPath(new URL("..", import.meta.url));
// Paseo 0.8 rewrites CommonJS interop helpers; prebundling preserves SDK initialization order.
const output = join(root, "server/generated/sdk.js");
await build({
  stdin: { contents: 'export { Sandbox, Snapshot } from "@vercel/sandbox";', resolveDir: root },
  bundle: true, platform: "node", format: "esm", target: "node24", minify: true,
  banner: { js: 'import { createRequire } from "node:module"; const require = createRequire(process.cwd() + "/package.json");' },
  outfile: output, logLevel: "silent",
});
// Paseo resolves type imports at install time, so the declarations must not reference @vercel/sandbox either.
const entry = join(root, "server/generated/sdk-entry.d.ts");
const types = join(root, "server/generated/sdk.d.ts");
await writeFile(entry, 'export { Sandbox, Snapshot } from "@vercel/sandbox";\n');
try {
  execFileSync(join(root, "node_modules/.bin/dts-bundle-generator"), [
    "--no-check", "--export-referenced-types", "--no-banner",
    "--external-inlines", "@vercel/sandbox", "--external-inlines", "@workflow/serde", "--external-inlines", "async-retry",
    "-o", types, entry,
  ], { cwd: root, stdio: "pipe" });
} finally { await rm(entry, { force: true }); }
const flat = (await readFile(types, "utf8")).replace(/from '(fs|stream)'/g, "from 'node:$1'");
await writeFile(types, flat);
await mkdir(join(root, "dist/server/generated"), { recursive: true });
await copyFile(output, join(root, "dist/server/generated/sdk.js"));
await copyFile(types, join(root, "dist/server/generated/sdk.d.ts"));

import test from "node:test";
import assert from "node:assert/strict";
const { logEvent } = await import("../dist/server/log.js");

test("plugin log lines never carry secrets", () => {
  const lines = [];
  const original = console.log; console.log = (line) => lines.push(String(line));
  try {
    logEvent("operation_failed", {
      agent: "codex", error: "operation_failed",
      detail: "bootstrap failed: AI_GATEWAY_API_KEY=[REDACTED] token: [REDACTED] https://app.paseo.sh/#offer=abc.def paseo://pair/xyz Bearer zzz",
    }, "vck_secret_123");
  } finally { console.log = original; }
  assert.equal(lines.length, 1);
  const parsed = JSON.parse(lines[0]);
  assert.equal(parsed.plugin, "vercel-sandbox"); assert.equal(parsed.event, "operation_failed"); assert.ok(parsed.at);
  for (const secret of ["vck_secret_123", "vercel-secret-456", "#offer=abc", "paseo://pair/xyz", "Bearer zzz"]) assert.ok(!lines[0].includes(secret), `log leaked ${secret}`);
});

test("redaction does not depend on knowing the key", () => {
  const lines = [];
  const original = console.log; console.log = (line) => lines.push(String(line));
  try { logEvent("operation_failed", { detail: 'bare vck_abcDEF123-_x and {"gatewayKey":"vck_other"} and gateway_key=vck_third' }); }
  finally { console.log = original; }
  for (const secret of ["vck_abcDEF123-_x", "vck_other", "vck_third"]) assert.ok(!lines[0].includes(secret), `log leaked ${secret}`);
});

import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { cpSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import assert from "node:assert/strict";

const root = fileURLToPath(new URL("..", import.meta.url));
const manifest = JSON.parse(readFileSync(join(root, "paseo-plugin.json"), "utf8"));
const pkg = JSON.parse(readFileSync(join(root, "package.json"), "utf8"));

assert.equal(manifest.id, "vercel-sandbox");
assert.equal(manifest.requirements.paseo, ">=0.8.0");
// Install must be a plain clone: the Paseo CLI gives up after 60 s, and a cold npm ci exceeds that.
assert.equal(manifest.build, undefined);
assert.equal(pkg.dependencies["@vercel/sandbox"], "3.3.0");
assert.equal(pkg.devDependencies["@getpaseo/plugin"], "0.8.0");
assert.equal(pkg.devDependencies.react, "19.1.0");
for (const forbidden of ["next", "@vercel/blob", "@vercel/oidc"]) {
  assert.equal(pkg.dependencies[forbidden], undefined);
  assert.equal(pkg.devDependencies[forbidden], undefined);
}
for (const required of [
  "index.client.tsx", "index.server.ts", "client/hosts.tsx", "client/settings.tsx",
  "shared/agents.ts", "shared/rpc.ts", "server/service.ts", "server/runtime.ts",
  "server/generated/sdk.js", "server/generated/sdk.d.ts", "package-lock.json",
]) assert.ok(statSync(join(root, required)).isFile(), `missing ${required}`);

// Runtime source may import only what Paseo supplies, Node builtins, local files, or the prebundled SDK.
const allowed = new Set(["@getpaseo/plugin", "@getpaseo/plugin/server", "@getpaseo/plugin/client", "@getpaseo/plugin/client/ui", "@getpaseo/plugin/client/react-native", "zod", "react", "react/jsx-runtime", "react-native"]);
function* sources(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) { if (entry.name !== "generated") yield* sources(path); }
    else if (/\.(ts|tsx)$/.test(entry.name)) yield path;
  }
}
const files = ["index.client.tsx", "index.server.ts"].map(f => join(root, f));
for (const dir of ["client", "server", "shared"]) files.push(...sources(join(root, dir)));
for (const file of files) {
  for (const match of readFileSync(file, "utf8").matchAll(/import\s+(type\s+)?[^;]*?from\s+"([^"]+)"/g)) {
    const spec = match[2];
    assert.notEqual(spec, "@vercel/sandbox", `${relative(root, file)} imports @vercel/sandbox; Paseo resolves type imports at install time, use ./sdk.js`);
    if (match[1]) continue; // other type-only imports are erased before Paseo resolves anything
    if (spec.startsWith(".") || spec.startsWith("node:")) continue;
    assert.ok(allowed.has(spec), `${relative(root, file)} imports ${spec}, which Paseo does not provide at runtime`);
  }
}

for (const match of readFileSync(join(root, "server/generated/sdk.d.ts"), "utf8").matchAll(/from '([^.'][^']*)'/g)) {
  assert.ok(match[1].startsWith("node:") || match[1] === "zod", `generated sdk.d.ts imports ${match[1]}, which is not installed on the daemon host`);
}
// The committed prebundle must be exactly what the lockfile produces, so a reviewer can rebuild it.
const digest = (dir) => ["sdk.js", "sdk.d.ts"].map(f => createHash("sha256").update(readFileSync(join(dir, "server/generated", f))).digest("hex")).join("+");
const committed = digest(root);
const temporary = mkdtempSync(join(tmpdir(), "paseo-vercel-sandbox-package-"));
const staged = join(temporary, "plugin");
cpSync(root, staged, { recursive: true, filter: (source) => !["node_modules", "dist"].some((name) => source === join(root, name) || source.startsWith(join(root, name) + "/")) });
const cache = process.env.PASEO_PLUGIN_NPM_CACHE ?? join(temporary, "npm-cache");
const npmEnv = { ...process.env, npm_config_cache: cache, npm_config_fetch_retries: "2", npm_config_fetch_timeout: "30000", npm_config_userconfig: "/dev/null", npm_config_registry: "https://registry.npmjs.org", NPM_CONFIG_REGISTRY: "https://registry.npmjs.org" };
execFileSync("npm", ["ci"], { cwd: staged, stdio: "pipe", env: npmEnv });
execFileSync("node", ["scripts/build-sdk.mjs"], { cwd: staged, stdio: "pipe", env: npmEnv });
assert.equal(digest(staged), committed, "committed server/generated/sdk.js or sdk.d.ts differs from a fresh build; run npm run build and commit both");
rmSync(temporary, { recursive: true, force: true });
console.log(`PASS clean package: no build step, runtime imports bounded, SDK prebundle reproducible (${committed.slice(0, 12)})`);

import test from "node:test";
import assert from "node:assert/strict";

const { applyGatewayPolicy, BROKERED_GATEWAY_KEY, GATEWAY_HOST, gatewayNetworkPolicy } = await import("../dist/server/network.js");

test("the Gateway key is injected by the firewall and everything else stays reachable", () => {
  const policy = gatewayNetworkPolicy("gateway-secret");
  assert.deepEqual(policy, {
    allow: {
      [GATEWAY_HOST]: [{ transform: [{ headers: { Authorization: "Bearer gateway-secret" } }] }],
      "*": [],
    },
  });
  assert.equal(GATEWAY_HOST, "ai-gateway.vercel.sh");
});

test("an empty key never produces a policy that would let requests out unauthenticated", () => {
  assert.throws(() => gatewayNetworkPolicy(""), /gateway key is required/);
});

test("the in-sandbox placeholder is not a usable key and differs from any real one", () => {
  assert.ok(BROKERED_GATEWAY_KEY.length > 0);
  assert.equal(BROKERED_GATEWAY_KEY.startsWith("vck_"), false);
  assert.notEqual(BROKERED_GATEWAY_KEY, "gateway-secret");
});

test("applyGatewayPolicy updates the running sandbox with the transform policy", async () => {
  const calls = [];
  await applyGatewayPolicy({ update: async (params, opts) => { calls.push([params, opts]); } }, "gateway-secret");
  assert.equal(calls.length, 1);
  assert.deepEqual(calls[0][0], { networkPolicy: gatewayNetworkPolicy("gateway-secret") });
});

import test from "node:test";
import assert from "node:assert/strict";

const { register } = await import("../dist/server/register.js");
const rpc = await import("../dist/shared/rpc.js");

const contracts = Object.values(rpc).filter((value) => value && typeof value === "object" && typeof value.name === "string");

function fakeServer() {
  const handlers = new Map();
  return { handlers, handle: (contract, handler) => { handlers.set(contract.name, handler); } };
}

function recordingService() {
  const calls = [];
  const record = (name) => (...args) => { calls.push([name, ...args]); return Promise.resolve({ name }); };
  return {
    calls,
    status: record("status"), act: record("act"), revealPairing: record("revealPairing"),
    saveCredentials: record("saveCredentials"), removeCredentials: record("removeCredentials"),
    dispose: record("dispose"),
  };
}

test("every RPC contract in shared/rpc.ts has a registered handler", () => {
  const server = fakeServer();
  register(server, recordingService());
  assert.ok(contracts.length >= 5, `expected at least 5 contracts, found ${contracts.length}`);
  for (const contract of contracts) assert.ok(server.handlers.has(contract.name), `${contract.name} is not registered`);
  assert.equal(server.handlers.size, contracts.length);
});

test("status handler forwards the client's refresh flag", async () => {
  const server = fakeServer();
  const service = recordingService();
  register(server, service);
  const status = server.handlers.get(rpc.statusRpc.name);
  await status({ refresh: true }, {});
  await status({}, {});
  await status({ refresh: false }, {});
  assert.deepEqual(service.calls, [["status", true], ["status", false], ["status", false]]);
});

test("act, reveal, save and remove handlers pass their inputs through", async () => {
  const server = fakeServer();
  const service = recordingService();
  register(server, service);
  await server.handlers.get(rpc.actRpc.name)({ agent: "codex", action: "start", confirm: undefined }, {});
  await server.handlers.get(rpc.revealPairingRpc.name)({ agent: "pi" }, {});
  const save = { teamId: "t", projectId: "p", replaceVercelToken: false, replaceGatewayKey: false };
  await server.handlers.get(rpc.saveCredentialsRpc.name)(save, {});
  await server.handlers.get(rpc.removeCredentialsRpc.name)({}, {});
  assert.deepEqual(service.calls, [
    ["act", "codex", "start", undefined], ["revealPairing", "pi"], ["saveCredentials", save], ["removeCredentials"],
  ]);
});

test("cleanup returns the dispose promise so Paseo can await worker shutdown", async () => {
  const service = recordingService();
  const cleanup = register(fakeServer(), service);
  const result = cleanup();
  assert.ok(result instanceof Promise);
  await result;
  assert.deepEqual(service.calls, [["dispose"]]);
});

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { createRequire } from "node:module";
import { spawn, execFileSync } from "node:child_process";
import { mkdtemp, mkdir, readFile, writeFile, cp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { pathToFileURL, fileURLToPath } from "node:url";
import { createServer } from "node:net";

assert.equal(process.env.PASEO_E2E_RUN, "1", "Set PASEO_E2E_RUN=1 to authorize four disposable billable sandboxes");
const plugin = resolve(process.env.PASEO_E2E_PLUGIN ?? fileURLToPath(new URL("..", import.meta.url)));
const cli = process.env.PASEO_E2E_CLI;
const browserPackage = process.env.PASEO_E2E_PLAYWRIGHT;
assert.ok(cli && browserPackage, "Set PASEO_E2E_CLI and PASEO_E2E_PLAYWRIGHT to a pinned Paseo CLI (0.8 or 0.9) and Playwright module paths");
// Controller CLI may be 0.8.x (flag-based start) or 0.9.x (`daemon run` plus persistent configuration).
const cliVersion = JSON.parse(await readFile(join(dirname(dirname(cli)), "package.json"), "utf8")).version;
assert.match(cliVersion, /^0\.9\./, `unsupported controller CLI version ${cliVersion}`);
const { chromium } = createRequire(import.meta.url)(browserPackage);
const { Sandbox, Snapshot } = await import(pathToFileURL(join(plugin, "dist/server/sdk.js")));
const { destroySandboxAndSnapshots } = await import(pathToFileURL(join(plugin, "dist/server/lifecycle.js")));
const credentials = {
  token: [REDACTED],
  teamId: process.env.VERCEL_TEAM_ID,
  projectId: process.env.VERCEL_PROJECT_ID,
  gateway: process.env.AI_GATEWAY_API_KEY,
};
for (const [name, value] of Object.entries(credentials)) assert.ok(value, `Missing ${name}`);
const privateValues = Object.values(credentials);
const safe = (input) => {
  let text = String(input);
  for (const value of privateValues) text = text.replaceAll(value, "[PRIVATE]");
  return text.replace(/https:\/\/app\.paseo\.sh\/[^\s"']+/g, "[PAIRING URL]");
};
const root = await mkdtemp(join(tmpdir(), "paseo-plugin-e2e-"));
const home = join(root, "home");
const stateRoot = join(root, "state");
await mkdir(home, { mode: 0o700 });
await writeFile(join(home, "config.json"), JSON.stringify({ pluginsEnabled: true, daemon: { mcp: { enabled: false }, relay: { enabled: false } } }), { mode: 0o600 });
const port = await new Promise((res, rej) => {
  const server = createServer(); server.once("error", rej);
  server.listen(0, "127.0.0.1", () => { const value = server.address().port; server.close(() => res(value)); });
});
const base = `http://127.0.0.1:${port}`;
const daemonEnv = { ...process.env, PASEO_HOME: home, PASEO_VERCEL_SANDBOX_STATE_DIR: stateRoot,
  npm_config_registry: "https://registry.npmjs.org", npm_config_userconfig: "/dev/null",
  npm_config_cache: join(root, "npm-cache"), npm_config_audit: "false", npm_config_fund: "false" };
for (const key of ["VERCEL_TOKEN", "VERCEL_OIDC_TOKEN", "AI_GATEWAY_API_KEY"]) delete daemonEnv[key];
const checks = [];
const report = { startedAt: new Date().toISOString(), passed: false, checks, cleanup: [], root };
const record = (name, details = {}) => { checks.push({ name, time: new Date().toISOString(), ...details }); console.log(`PASS ${name}`); };
const delay = (ms) => new Promise((res) => setTimeout(res, ms));
async function until(fn, label, timeout = 120000) {
  const end = Date.now() + timeout;
  while (Date.now() < end) { if (await fn()) return; await delay(500); }
  throw new Error(`Timed out: ${label}`);
}
async function slot(agent) {
  try { return JSON.parse(await readFile(join(stateRoot, "slots", `${agent}.json`), "utf8")); }
