import { redactText } from "./providers.js";

// One JSON line per event on stdout, which Paseo exposes through `paseo plugin logs vercel-sandbox`.
// Every line passes through redactText so a Gateway key, token, or pairing offer never reaches the log.
export function logEvent(event: string, fields: Record<string, unknown>, secret?: string): void {
  const line = JSON.stringify({ plugin: "vercel-sandbox", event, ...fields, at: new Date().toISOString() });
  console.log(redactText(line, secret));
}

import type { NetworkPolicy, Sandbox } from "./sdk.js";

export const GATEWAY_HOST = "ai-gateway.vercel.sh";

// What the sandbox sees instead of the Gateway key. Agents refuse to start
// with an empty key, so a visible placeholder goes into their env and config
// files; the firewall replaces the Authorization header on the way out.
export const BROKERED_GATEWAY_KEY = "brokered-by-vercel-sandbox-firewall";

export function gatewayNetworkPolicy(gatewayKey: string): NetworkPolicy {
  if (!gatewayKey) throw new Error("gateway key is required to build the network policy");
  return {
    allow: {
      [GATEWAY_HOST]: [{ transform: [{ headers: { Authorization: `Bearer ${gatewayKey}` } }] }],
      "*": [],
    },
  };
}

export async function applyGatewayPolicy(
  sandbox: Pick<Sandbox, "update">,
  gatewayKey: string,
  signal?: AbortSignal,
): Promise<void> {
  await sandbox.update({ networkPolicy: gatewayNetworkPolicy(gatewayKey) }, { signal });
}

import type { PluginServerContext } from "@getpaseo/plugin/server";
import type { RpcInput, RpcOutput } from "@getpaseo/plugin";
import {
  actRpc,
  removeCredentialsRpc,
  revealPairingRpc,
  saveCredentialsRpc,
  statusRpc,
} from "../shared/rpc.js";

export interface RegisteredService {
  status(refresh?: boolean): Promise<RpcOutput<typeof statusRpc>>;
  act(agent: RpcInput<typeof actRpc>["agent"], action: RpcInput<typeof actRpc>["action"], confirm?: string): Promise<RpcOutput<typeof actRpc>>;
  revealPairing(agent: RpcInput<typeof revealPairingRpc>["agent"]): Promise<RpcOutput<typeof revealPairingRpc>>;
  saveCredentials(input: RpcInput<typeof saveCredentialsRpc>): Promise<RpcOutput<typeof saveCredentialsRpc>>;
  removeCredentials(): Promise<RpcOutput<typeof removeCredentialsRpc>>;
  dispose(): Promise<void>;
}

// Every contract in shared/rpc.ts must be registered here; test/register.test.mjs checks the list.
export function register(server: Pick<PluginServerContext, "handle">, service: RegisteredService): () => Promise<void> {
  server.handle(statusRpc, (input) => service.status(input.refresh ?? false));
  server.handle(actRpc, (input) => service.act(input.agent, input.action, input.confirm));
  server.handle(revealPairingRpc, (input) => service.revealPairing(input.agent));
  server.handle(saveCredentialsRpc, (input) => service.saveCredentials(input));
  server.handle(removeCredentialsRpc, () => service.removeCredentials());
  return () => service.dispose();
}

